class EightPuzzle:
    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return i, j
        return None

    def move(self, state, direction):
        r, c = self.find_blank(state)
        moves = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
        dr, dc = moves[direction]
        nr, nc = r + dr, c + dc

        if 0 <= nr < 3 and 0 <= nc < 3:
            new_state = copy.deepcopy(state)
            new_state[r][c], new_state[nr][nc] = new_state[nr][nc], new_state[r][c]
            return new_state
        return None

    def get_possible_moves(self, state):
        r, c = self.find_blank(state)
        possible = []
        if r > 0: possible.append('up')
        if r < 2: possible.append('down')
        if c > 0: possible.append('left')
        if c < 2: possible.append('right')
        return possible

    def solve(self):
        # Queue stores (current_state, path_list)
        queue = deque([(self.initial_state, [])])
        visited = {str(self.initial_state)}

        while queue:
            current_state, path = queue.popleft()

            if current_state == self.goal_state:
                return path

            for direction in self.get_possible_moves(current_state):
                new_state = self.move(current_state, direction)
                state_str = str(new_state)
                if state_str not in visited:
                    visited.add(state_str)
                    queue.append((new_state, path + [direction]))
        return None

