class ExpressionCalculator:
    def __init__(self):
        self.postfix_stack = deque()
        # Priority map: +, -, *, /, %, (, )
        # Using indices for comparison
        self.ops = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '(': 0, ')': 0}

    def transform(self, expression):
        return expression.replace(" ", "")

    @staticmethod
    def is_operator(c):
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        # Returns True if cur has higher or equal precedence than peek
        return self.ops.get(cur, 0) <= self.ops.get(peek, 0)

    def prepare(self, expression):
        self.postfix_stack = deque()
        operator_stack = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = ""
                while i < len(expression) and expression[i].isdigit():
                    num += expression[i]
                    i += 1
                self.postfix_stack.append(num)
                continue
            elif expression[i] == '(':
                operator_stack.append('(')
            elif expression[i] == ')':
                while operator_stack and operator_stack[-1] != '(':
                    self.postfix_stack.append(operator_stack.pop())
                operator_stack.pop() # remove '('
            else:
                while operator_stack and self.compare(expression[i], operator_stack[-1]):
                    self.postfix_stack.append(operator_stack.pop())
                operator_stack.append(expression[i])
            i += 1
        while operator_stack:
            self.postfix_stack.append(operator_stack.pop())

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        a, b = float(first_value), float(second_value)
        if current_op == '+': return a + b
        if current_op == '-': return a - b
        if current_op == '*': return a * b
        if current_op == '/': return a / b
        if current_op == '%': return a % b
        return 0.0

    def calculate(self, expression):
        expr = self.transform(expression)
        self.prepare(expr)

        eval_stack = []
        for token in self.postfix_stack:
            if not self.is_operator(token):
                eval_stack.append(token)
            else:
                val2 = eval_stack.pop()
                val1 = eval_stack.pop()
                res = self._calculate(val1, val2, token)
                eval_stack.append(str(res))
        return float(eval_stack[0])

