import socket

class IpUtil:
    """
    This is a class as tool for ip that can be used to obtain the local IP address, 
    validate its validity, and also provides the functionality to retrieve the 
    corresponding hostname.
    """

    @staticmethod
    def is_valid_ipv4(ip_address):
        """
        Check if the given IP address is a valid IPv4 address.
        """
        try:
            # inet_aton converts an IP string to 32-bit packed binary format
            socket.inet_aton(ip_address)
            # Ensure it's strictly dot-decimal (inet_aton is sometimes too lenient)
            return ip_address.count('.') == 3
        except (socket.error, AttributeError, TypeError):
            return False

    @staticmethod
    def is_valid_ipv6(ip_address):
        """
        Check if the given IP address is a valid IPv6 address.
        """
        try:
            # inet_pton converts an IP string to binary format for AF_INET6
            socket.inet_pton(socket.AF_INET6, ip_address)
            return True
        except (socket.error, AttributeError, TypeError):
            return False

    @staticmethod
    def get_hostname(ip_address):
        """
        Get the hostname associated with the given IP address.
        Returns None if the hostname cannot be resolved.
        """
        try:
            # gethostbyaddr returns a tuple (hostname, aliaslist, ipaddrlist)
            data = socket.gethostbyaddr(ip_address)
            return data[0]
        except (socket.herror, socket.gaierror, socket.error):
            # herror is raised when the host is unknown
            return None

class JobMarketplace:
    """
    This is a class that provides functionalities to publish positions, remove positions, 
    submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    """

    def __init__(self):
        self.job_listings = []
        self.resumes = []

    def post_job(self, job_title, company, requirements):
        job = {
            'job_title': job_title,
            'company': company,
            'requirements': requirements
        }
        self.job_listings.append(job)

    def remove_job(self, job):
        if job in self.job_listings:
            self.job_listings.remove(job)

    def submit_resume(self, name, skills, experience):
        resume = {
            'name': name,
            'skills': skills,
            'experience': experience
        }
        self.resumes.append(resume)

    def withdraw_resume(self, resume):
        if resume in self.resumes:
            self.resumes.remove(resume)

    def search_jobs(self, criteria):
        results = []
        for job in self.job_listings:
            if criteria in job['requirements']:
                results.append(job)
        return results

    def get_job_applicants(self, job):
        applicants = []
        job_reqs = set(job['requirements'])

        for resume in self.resumes:
            candidate_skills = set(resume['skills'])
            # Check if all job requirements are covered by candidate skills
            if job_reqs.issubset(candidate_skills):
                applicants.append(resume)
        return applicants

