        data = self.read_json(file_path)

        # Handle cases where read_json failed or file missing
        if data == 0 or data == -1:
            return 0

        # Check if key exists
        if remove_key not in data:
            return 0

        # Remove key and write back
        del data[remove_key]
        result = self.write_json(data, file_path)

        # If write was successful, return 1, else 0 (or handle error)
        return 1 if result == 1 else 0

