        """
        Checks if a path exists with at most 2 turns.
        Uses a simple BFS approach tracking turns.
        """
        rows, cols = self.BOARD_SIZE
        # Queue stores: (r, c, last_direction, turns_count)
        # Directions: 0:None, 1:Up, 2:Down, 3:Left, 4:Right
        queue = [(pos1[0], pos1[1], 0, 0)]
        visited = set()

        while queue:
            r, c, last_dir, turns = queue.pop(0)

            if (r, c) == pos2:
                return True

            if turns > 2:
                continue

            for dr, dc, direction in [(-1, 0, 1), (1, 0, 2), (0, -1, 3), (0, 1, 4)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_turns = turns + (1 if (last_dir != 0 and last_dir != direction) else 0)
                    if new_turns <= 2:
                        if (nr, nc) == pos2 or self.board[nr][nc] == ' ':
                            if (nr, nc, direction, new_turns) not in visited:
                                visited.add((nr, nc, direction, new_turns))
                                queue.append((nr, nc, direction, new_turns))
        return False

    def remove_icons(self, pos1, pos2):
        self.board[pos1[0]][pos1[1]] = ' '
        self.board[pos2[0]][pos2[1]] = ' '

    def is_game_over(self):
        for row in self.board:
            for cell in row:
                if cell != ' ':
                    return False
        return True

class MetricsCalculator:
    """
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    """

    def __init__(self):
        self.true_positives = 0
        self.false_positives = 0
        self.false_negatives = 0
        self.true_negatives = 0

    def update(self, predicted_labels, true_labels):
        """Update the internal counts based on input lists."""
        for p, t in zip(predicted_labels, true_labels):
            if p == 1 and t == 1:
                self.true_positives += 1
            elif p == 1 and t == 0:
                self.false_positives += 1
            elif p == 0 and t == 1:
                self.false_negatives += 1
            elif p == 0 and t == 0:
                self.true_negatives += 1

    def precision(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        denominator = self.true_positives + self.false_positives
        return self.true_positives / denominator if denominator != 0 else 0.0

    def recall(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        denominator = self.true_positives + self.false_negatives
        return self.true_positives / denominator if denominator != 0 else 0.0

    def f1_score(self, predicted_labels, true_labels):
        p = self.precision(predicted_labels, true_labels)
        r = self.recall(predicted_labels, true_labels)
        denominator = p + r
        return 2 * (p * r) / denominator if denominator != 0 else 0.0

    def accuracy(self, predicted_labels, true_labels):
        self.update(predicted_labels, true_labels)
        total = self.true_positives + self.false_positives + self.false_negatives + self.true_negatives
        correct = self.true_positives + self.true_negatives
        return correct / total if total != 0 else 0.0

import numpy as np

class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP).
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        # Ensure data is a list of tuples for uniform processing
        if isinstance(data, tuple):
            data = [data]

        reciprocal_ranks = []
        for results, _ in data:
            try:
                # Find index of first 1
                rank = results.index(1) + 1
                reciprocal_ranks.append(1.0 / rank)
            except ValueError:
                # No 1 found in the list
                reciprocal_ranks.append(0.0)

        return np.mean(reciprocal_ranks), reciprocal_ranks

    @staticmethod
    def map(data):
        # Ensure data is a list of tuples for uniform processing
        if isinstance(data, tuple):
            data = [data]

        average_precisions = []
        for results, ground_truth_num in data:
            if ground_truth_num == 0:
                average_precisions.append(0.0)
                continue

            relevant_count = 0
            precision_sum = 0.0

            for i, val in enumerate(results):
                if val == 1:
                    relevant_count += 1
                    precision_at_k = relevant_count / (i + 1)
                    precision_sum += precision_at_k

            # AP = sum(precision at each relevant rank) / total ground truth
            ap = precision_sum / ground_truth_num
            average_precisions.append(ap)

        return np.mean(average_precisions), average_precisions

import random

class MinesweeperGame:
    def __init__(self, n, k) -> None:
        self.n = n
        self.k = k
        self.minesweeper_map = self.generate_mine_sweeper_map()
        self.player_map = self.generate_playerMap()
        self.score = 0

    def generate_mine_sweeper_map(self):
        grid = [[0 for _ in range(self.n)] for _ in range(self.n)]
        mines = set()
        while len(mines) < self.k:
            mines.add((random.randint(0, self.n - 1), random.randint(0, self.n - 1)))

        for r, c in mines:
            grid[r][c] = 'X'

        for r in range(self.n):
            for c in range(self.n):
                if grid[r][c] == 'X':
                    continue
                count = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < self.n and 0 <= nc < self.n and grid[nr][nc] == 'X':
                            count += 1
                grid[r][c] = count
        return grid

    def generate_playerMap(self):
        return [['-' for _ in range(self.n)] for _ in range(self.n)]

    def check_won(self, map):
        hidden_count = sum(row.count('-') for row in map)
        return hidden_count == self.k

    def sweep(self, x, y):
        # If already swept or invalid, return current map
        if self.player_map[x][y] != '-':
            return self.player_map

        # If hit a mine
        if self.minesweeper_map[x][y] == 'X':
            return "Game Over"

        # Reveal cell
        self.player_map[x][y] = self.minesweeper_map[x][y]

        # Check win condition
        if self.check_won(self.player_map):
            return True

        return self.player_map

