import numpy as np

class MovieBookingSystem:
    """
    This is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range. 
    """

    def __init__(self):
        self.movies = []

    def add_movie(self, name, price, start_time, end_time, n):
        # Convert time strings to datetime objects
        start = datetime.strptime(start_time, '%H:%M')
        end = datetime.strptime(end_time, '%H:%M')

        # Create seat matrix
        seats = np.zeros((n, n))

        movie = {
            'name': name,
            'price': price,
            'start_time': start,
            'end_time': end,
            'seats': seats
        }
        self.movies.append(movie)

    def book_ticket(self, name, seats_to_book):
        movie = next((m for m in self.movies if m['name'] == name), None)

        if not movie:
            return "Movie not found."

        # Check if all requested seats are available (0)
        for r, c in seats_to_book:
            if movie['seats'][r, c] != 0:
                return "Booking failed."

        # If all available, mark as booked (1)
        for r, c in seats_to_book:
            movie['seats'][r, c] = 1

        return "Booking success."

    def available_movies(self, start_time, end_time):
        start_range = datetime.strptime(start_time, '%H:%M')
        end_range = datetime.strptime(end_time, '%H:%M')

        available = []
        for movie in self.movies:
            # Check if movie time is within the range
            if movie['start_time'] >= start_range and movie['end_time'] <= end_range:
                available.append(movie['name'])

        return available

class NumberConverter:
