    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        """
        return int(hex_num, 16)

class NumberWordFormatter:
    def __init__(self):
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        self.NUMBER_TEN = ["", "", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION", "TRILLION"]

    def format(self, x):
        return self.format_string(str(x))

    def format_string(self, x):
        # Handle integer part
        parts = x.split('.')
        integer_part = parts[0]

        # Split into groups of 3
        groups = []
        while integer_part:
            groups.append(integer_part[-3:])
            integer_part = integer_part[:-3]

        res = []
        for i, group in enumerate(groups):
            word = self.trans_three(group)
            if word:
                suffix = self.parse_more(i)
                res.append(f"{word} {suffix}".strip())

        return " ".join(reversed(res)).strip() + " ONLY"

    def trans_two(self, s):
        n = int(s)
        if n < 10:
            return self.NUMBER[n]
        elif n < 20:
            return self.NUMBER_TEEN[n - 10]
        else:
            tens = self.NUMBER_TEN[n // 10]
            ones = self.NUMBER[n % 10]
            return f"{tens} {ones}".strip()

    def trans_three(self, s):
        n = int(s)
        if n == 0: return ""

        if len(s) == 3 and s[0] != '0':
            hundreds = f"{self.NUMBER[int(s[0])]} HUNDRED"
            remainder = self.trans_two(s[1:])
            return f"{hundreds} AND {remainder}".strip() if remainder else hundreds
        else:
            return self.trans_two(s.lstrip('0'))

    def parse_more(self, i):
        if i < len(self.NUMBER_MORE):
            return self.NUMBER_MORE[i]
        return ""

import re

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities 
    with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string 
        with their corresponding Unicode characters.
        """
        def unescape_match(match):
            entity = match.group(1)
            try:
                if entity.lower().startswith('x'):
                    # Hexadecimal: &#x...;
                    code = int(entity[1:], 16)
                else:
                    # Decimal: &#...;
                    code = int(entity, 10)
                return chr(code)
            except (ValueError, OverflowError):
                # If the entity is invalid, return the original match
                return match.group(0)

        # Regex explanation:
        # &# : matches the literal start
        # (x?[0-9a-fA-F]+) : captures the numeric part (hex or decimal)
        # ; : matches the literal end
        return re.sub(r'&#(x?[0-9a-fA-F]+);', unescape_match, string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        """
        if not isinstance(char, str) or len(char) != 1:
            return False
        return char.isdigit() or char.lower() in 'abcdef'

