import re

class RegexUtils:
    """
    The class provides to match, find all occurrences, split, and substitute text using regular expressions.
    """

    def match(self, pattern, text):
        # Use bool() to convert the match object to True/False
        return bool(re.search(pattern, text))

    def findall(self, pattern, text):
        return re.findall(pattern, text)

    def split(self, pattern, text):
        return re.split(pattern, text)

    def sub(self, pattern, replacement, text):
        return re.sub(pattern, replacement, text)

    def generate_email_pattern(self):
        return r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'

    def generate_phone_number_pattern(self):
        return r'\b\d{3}-\d{3}-\d{4}\b'

    def generate_split_sentences_pattern(self):
        return r'[.!?][\s]{1,2}(?=[A-Z])'

    def split_sentences(self, text):
        # Split using the pattern
        parts = re.split(self.generate_split_sentences_pattern(), text)
        # The requirement asks to keep punctuation for the last sentence.
        # The split removes the punctuation. We can re-append it if needed, 
        # but based on the example, we split and return the list.
        return parts

    def validate_phone_number(self, phone_number):
        pattern = self.generate_phone_number_pattern()
        # Ensure the whole string matches the phone pattern
        return bool(re.fullmatch(pattern, phone_number))

    def extract_email(self, text):
        pattern = self.generate_email_pattern()
        return self.findall(pattern, text)

class RPGCharacter:
    """
    The class represents a role-playing game character, which allows to attack other characters, heal, gain experience, level up, and check if the character is alive.
    """

    def __init__(self, name, hp, attack_power, defense, level=1):
        self.name = name
        self.hp = hp
        self.attack_power = attack_power
        self.defense = defense
        self.level = level
        self.exp = 0

    def attack(self, other_character):
        damage = max(0, self.attack_power - other_character.defense)
        other_character.hp -= damage

    def heal(self):
        self.hp = min(100, self.hp + 10)
        return self.hp

    def gain_exp(self, amount):
        self.exp += amount
        # While we have enough exp to level up and haven't hit max level
        while self.exp >= (self.level * 100) and self.level < 100:
            self.exp -= (self.level * 100)
            self.level_up()

    def level_up(self):
        if self.level < 100:
            self.level += 1
            self.hp += 20
            self.attack_power += 5
            self.defense += 5
        return (self.level, self.hp, self.attack_power, self.defense)

    def is_alive(self):
        return self.hp > 0

