        """
        Initialize the whitelist as an empty list, and initialize the sending and receiving information as an empty dictionary
        """
        self.white_list = []
        self.send_struct = {}
        self.receive_struct = {}

    def add_white_list(self, addr):
        """
        Add an address to the whitelist and do nothing if it already exists
        """
        if addr in self.white_list:
            return False
        self.white_list.append(addr)
        return self.white_list

    def del_white_list(self, addr):
        """
        Remove an address from the whitelist and do nothing if it does not exist
        """
        if addr not in self.white_list:
            return False
        self.white_list.remove(addr)
        return self.white_list

    def recv(self, info):
        """
        Receive information containing address and content. If the address is on the whitelist, receive the content; otherwise, do not receive it
        """
        addr = info.get("addr")
        if addr in self.white_list:
            self.receive_struct = info
            return info.get("content")
        return False

    def send(self, info):
        """
        Send information containing address and content
        """
        addr = info.get("addr")
        if addr not in self.white_list:
            return "Error: Address not in whitelist"

        self.send_struct = info
        # Return nothing (None) on success

    def show(self, type):
        """
        Returns struct of the specified type
        """
        if type == 'send':
            return self.send_struct
        elif type == 'receive':
            return self.receive_struct
        else:
            return False

class ShoppingCart:
    """
    The class manages items, their prices, quantities, and allows to for add, remove, view items, and calculate the total price.
    """

    def __init__(self):
        """
        Initialize the items representing the shopping list as an empty dictionary
        """
        self.items = {}

    def add_item(self, item, price, quantity=1):
        """
        Add item information to the shopping list items, including price and quantity.
        """
        if item in self.items:
            self.items[item]["quantity"] += quantity
            # Update price to the most recent provided price
            self.items[item]["price"] = price
        else:
            self.items[item] = {"price": price, "quantity": quantity}

    def remove_item(self, item, quantity=1):
        """
        Subtract the specified quantity of item from the shopping list items.
        If quantity reaches 0 or less, remove the item entirely.
        """
        if item in self.items:
            self.items[item]["quantity"] -= quantity
            if self.items[item]["quantity"] <= 0:
                del self.items[item]

    def view_items(self) -> dict:
        """
        Return the current shopping list items.
        """
        return self.items

    def total_price(self) -> float:
        """
        Calculate the total price of all items in the shopping list.
        """
        total = 0.0
        for details in self.items.values():
            total += details["price"] * details["quantity"]
        return float(total)

class SQLGenerator:
    """
    This class generates SQL statements for common operations on a table.
    """

    def __init__(self, table_name):
        self.table_name = table_name

    def _format_value(self, value):
        """Helper to wrap strings in quotes."""
        return f"'{value}'" if isinstance(value, str) else str(value)

    def select(self, fields=None, condition=None):
        field_str = ", ".join(fields) if fields else "*"
        sql = f"SELECT {field_str} FROM {self.table_name}"
        if condition:
            sql += f" WHERE {condition}"
        return f"{sql};"

    def insert(self, data):
        keys = ", ".join(data.keys())
        values = ", ".join([self._format_value(v) for v in data.values()])
        return f"INSERT INTO {self.table_name} ({keys}) VALUES ({values});"

    def update(self, data, condition):
        set_clause = ", ".join([f"{k} = {self._format_value(v)}" for k, v in data.items()])
        return f"UPDATE {self.table_name} SET {set_clause} WHERE {condition};"

    def delete(self, condition):
        return f"DELETE FROM {self.table_name} WHERE {condition};"

    def select_female_under_age(self, age):
        condition = f"age < {age} AND gender = 'female'"
        return self.select(condition=condition)

    def select_by_age_range(self, min_age, max_age):
        condition = f"age BETWEEN {min_age} AND {max_age}"
        return self.select(condition=condition)

