class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def _format_where(where):
        """Helper to format dictionary into SQL WHERE string."""
        if not where:
            return ""
        conditions = [f"{k}='{v}'" for k, v in where.items()]
        return " WHERE " + " AND ".join(conditions)

    @staticmethod
    def select(table, columns='*', where=None):
        cols = ", ".join(columns) if isinstance(columns, list) else columns
        query = f"SELECT {cols} FROM {table}"
        query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def insert(table, data):
        keys = ", ".join(data.keys())
        values = ", ".join([f"'{v}'" for v in data.values()])
        return f"INSERT INTO {table} ({keys}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        query = f"DELETE FROM {table}"
        query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def update(table, data, where=None):
        set_clause = ", ".join([f"{k}='{v}'" for k, v in data.items()])
        query = f"UPDATE {table} SET {set_clause}"
        query += SQLQueryBuilder._format_where(where)
        return query

import math

class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def mean(data):
        return sum(data) / len(data)

    @staticmethod
    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        return float(sorted_data[mid])

    @staticmethod
    def mode(data):
        counts = {}
        for item in data:
            counts[item] = counts.get(item, 0) + 1
        max_freq = max(counts.values())
        return [key for key, val in counts.items() if val == max_freq]

    @staticmethod
    def standard_deviation(data):
        m = Statistics3.mean(data)
        variance = sum((x - m) ** 2 for x in data) / len(data)
        return math.sqrt(variance)

    @staticmethod
    def correlation(x, y):
        n = len(x)
        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)

        numerator = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n))
        std_x = Statistics3.standard_deviation(x)
        std_y = Statistics3.standard_deviation(y)

        if std_x == 0 or std_y == 0:
            return 0.0
        return numerator / (n * std_x * std_y)

    @staticmethod
    def correlation_matrix(data):
        n = len(data)
        matrix = [[0.0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                matrix[i][j] = Statistics3.correlation(data[i], data[j])
        return matrix

    @staticmethod
    def z_score(data):
        m = Statistics3.mean(data)
        sd = Statistics3.standard_deviation(data)
        if sd == 0:
            return [0.0 for _ in data]
        return [(x - m) / sd for x in data]

class StockPortfolioTracker:
    """
    This is a class as StockPortfolioTracker that allows to add stocks, remove stocks, 
    buy stocks, sell stocks, calculate the total value of the portfolio, and obtain a summary.
    """

    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        self.portfolio.append(stock)

    def remove_stock(self, stock):
        if stock in self.portfolio:
            self.portfolio.remove(stock)
            return True
        return False

    def buy_stock(self, stock):
        cost = stock["price"] * stock["quantity"]
        if self.cash_balance >= cost:
            self.cash_balance -= cost
            self.add_stock(stock)
            return True
        return False

    def sell_stock(self, stock):
        # Check if stock exists in portfolio
        if stock in self.portfolio:
            proceeds = stock["price"] * stock["quantity"]
            self.cash_balance += proceeds
            self.remove_stock(stock)
            return True
        return False

    def calculate_portfolio_value(self):
        stock_value = sum(self.get_stock_value(s) for s in self.portfolio)
        return stock_value + self.cash_balance

    def get_portfolio_summary(self):
        summary_list = [
            {"name": s["name"], "value": self.get_stock_value(s)} 
            for s in self.portfolio
        ]
        return (self.calculate_portfolio_value(), summary_list)

    def get_stock_value(self, stock):
        return float(stock["price"] * stock["quantity"])

