class Thermostat:
    """
    The class manages temperature control, including setting and retrieving the target temperature, 
    adjusting the mode, and simulating temperature operation.
    """

    def __init__(self, current_temperature, target_temperature, mode):
        self.current_temperature = float(current_temperature)
        self.target_temperature = float(target_temperature)
        self.mode = mode

    def get_target_temperature(self):
        return self.target_temperature

    def set_target_temperature(self, temperature):
        self.target_temperature = float(temperature)

    def get_mode(self):
        return self.mode

    def set_mode(self, mode):
        if mode in ['heat', 'cool']:
            self.mode = mode
        else:
            raise ValueError("Mode must be 'heat' or 'cool'")

    def auto_set_mode(self):
        if self.current_temperature < self.target_temperature:
            self.mode = 'heat'
        elif self.current_temperature > self.target_temperature:
            self.mode = 'cool'

    def auto_check_conflict(self):
        conflict = False
        if self.mode == 'heat' and self.current_temperature >= self.target_temperature:
            conflict = True
        elif self.mode == 'cool' and self.current_temperature <= self.target_temperature:
            conflict = True

        if conflict:
            self.auto_set_mode()
            return False
        return True

    def simulate_operation(self):
        self.auto_set_mode()
        steps = 0

        # Simulate adjustment until target is reached
        while self.current_temperature != self.target_temperature:
            if self.mode == 'heat':
                self.current_temperature += 1.0
                if self.current_temperature > self.target_temperature:
                    self.current_temperature = self.target_temperature
            elif self.mode == 'cool':
                self.current_temperature -= 1.0
                if self.current_temperature < self.target_temperature:
                    self.current_temperature = self.target_temperature

            steps += 1

        return steps

import numpy as np
from gensim import matutils

class VectorUtil:
    """
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    """

    @staticmethod
    def similarity(vector_1, vector_2):
        """Compute the cosine similarity between one vector and another vector."""
        v1 = matutils.unitvec(vector_1)
        v2 = matutils.unitvec(vector_2)
        return np.dot(v1, v2)

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        """Compute cosine similarities between one vector and a set of other vectors."""
        # Normalize the input vector
        v1 = matutils.unitvec(vector_1)
        # Normalize all vectors in the list
        v_all = np.array([matutils.unitvec(v) for v in vectors_all])
        # Dot product of v1 with all vectors in v_all
        return np.dot(v_all, v1)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        """Compute cosine similarity between two sets of vectors."""
        # Calculate the mean vector for each list
        v1_mean = np.mean(vector_list_1, axis=0)
        v2_mean = np.mean(vector_list_2, axis=0)
        # Return similarity of the centroids
        return VectorUtil.similarity(v1_mean, v2_mean)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        """Calculate log(total_num+1/count+1) for each count in number_dict."""
        idf_dict = {}
        for key, count in number_dict.items():
            # Formula: log((total_num + 1) / (count + 1))
            idf_dict[key] = np.log((total_num + 1) / (count + 1))
        return idf_dict

class VendingMachine:
    """
    This is a class to simulate a vending machine, including adding products, 
    inserting coins, purchasing products, viewing balance, replenishing 
    product inventory, and displaying product information.
    """

    def __init__(self):
        self.inventory = {}
        self.balance = 0

    def add_item(self, item_name, price, quantity):
        self.inventory[item_name] = {'price': price, 'quantity': quantity}

    def insert_coin(self, amount):
        self.balance += amount
        return self.balance

    def purchase_item(self, item_name):
        if item_name not in self.inventory:
            return False

        item = self.inventory[item_name]
        if item['quantity'] > 0 and self.balance >= item['price']:
            item['quantity'] -= 1
            self.balance -= item['price']
            return self.balance

        return False

    def restock_item(self, item_name, quantity):
        if item_name in self.inventory:
            self.inventory[item_name]['quantity'] += quantity
            return True
        return False

    def display_items(self):
        if not self.inventory:
            return False

        items_list = []
        for name, info in self.inventory.items():
            items_list.append(f"{name} - ${info['price']} [{info['quantity']}]")

        return "\n".join(items_list)

class Warehouse:
    def __init__(self):
        self.inventory = {}  # Product ID: {'name': str, 'quantity': int}
        self.orders = {}     # Order ID: {'product_id': int, 'quantity': int, 'status': str}

